package com.mvohm.quadruple.testdata.generators;

import java.math.BigInteger;
import java.util.Random;
import java.util.stream.DoubleStream;
import java.util.stream.LongStream;
import java.util.stream.Stream;

import com.mvohm.quadruple.Quadruple;
import com.mvohm.quadruple.testdata.Ieee754Bits;
import com.mvohm.quadruple.testdata.QuadParts;

/**
 * Generator of pseudo-random test values.
 * <p>
 * Each instance has its own {@link Random} with a fixed seed, so that every data set
 * is reproducible and independent of other data sets and of the order of test execution.
 * <p>
 * Values are generated by their bit patterns, not uniformly over the numeric range:
 * a uniform distribution over {@code [Double.MIN_VALUE, Double.MAX_VALUE]} would yield
 * only positive values of order 1e306..1e308.
 */
public class RandomGenerator {

  public static final long DEFAULT_RANDOM_SEED = 1234567890;

  private static final long DOUBLE_SIGN_MASK = 0x8000_0000_0000_0000L;
  private static final long DOUBLE_MANT_MASK = 0x000F_FFFF_FFFF_FFFFL;

  private final Random random;

  public RandomGenerator() {
    this(DEFAULT_RANDOM_SEED);
  }

  public RandomGenerator(long seed) {
    random = new Random(seed);
  }

  /**
   * Returns finite doubles with random bit patterns:
   * both signs, exponents evenly distributed over the whole range.
   * NaN and infinities are excluded (they are covered by constant data).
   * Subnormal values occur rarely here (about 1/2048), use {@link #subnormalDoubles(int)} for them.
   */
  public DoubleStream doubles(int count) {
    return DoubleStream.generate(() -> Double.longBitsToDouble(random.nextLong()))
                       .filter(Double::isFinite)
                       .limit(count);
  }

  /**
   * Returns subnormal doubles (exponent field == 0) of both signs.
   * The mantissa is shifted right by a random distance, so that the position
   * of its most significant bit is evenly distributed over all 52 bits.
   * Zeros are excluded.
   */
  public DoubleStream subnormalDoubles(int count) {
    return DoubleStream.generate(() -> {
        final long mant = (random.nextLong() & DOUBLE_MANT_MASK) >>> random.nextInt(52);
        final long sign = random.nextLong() & DOUBLE_SIGN_MASK;
        return Double.longBitsToDouble(sign | mant);
      })
      .filter(d -> d != 0)
      .limit(count);
  }

  /**
   * Returns finite floats with random bit patterns, both signs, exponents evenly distributed
   * over the whole range; about 1/4 of them are subnormal. Zeros are excluded.
   */
  public Stream<Float> floats(int count) {
    return Stream.generate(() -> random.nextInt(4) == 0?
                                   Float.intBitsToFloat(random.nextInt() & 0x807F_FFFF) :     // subnormal
                                   Float.intBitsToFloat(random.nextInt()))
                 .filter(f -> Float.isFinite(f) && f != 0)
                 .limit(count);
  }

  /**
   * Returns longs of both signs whose magnitudes are evenly distributed
   * over bit lengths from 1 to 64 (not concentrated near 2^63).
   */
  public LongStream longs(int count) {
    return LongStream.generate(() -> random.nextLong() >> random.nextInt(64))
                     .limit(count);
  }

  /**
   * Returns arbitrary random parts of Quadruple values: random sign, exponent, and mantissa.
   * All bit patterns are possible, including zero, NaN and infinity ones
   * (with a very low probability, though).
   */
  public Stream<QuadParts> quadrupleParts(int count) {
    return Stream.generate(() -> new QuadParts(random.nextBoolean(), random.nextInt(),
                                               random.nextLong(), random.nextLong()))
                 .limit(count);
  }

  /**
   * Returns bits of random finite IEEE-754 quadruple-precision values of both signs.
   * About 1/4 of them are subnormal, with the most significant bit of the significand
   * evenly distributed over all 112 positions; the rest are normal, with exponents
   * evenly distributed over the whole range. Zeros are excluded.
   */
  public Stream<Ieee754Bits> ieee754Bits(int count) {
    return Stream.generate(() -> {
        final long sign = random.nextBoolean()? 0x8000_0000_0000_0000L : 0;
        final boolean subnormal = random.nextInt(4) == 0;
        final long exponent = subnormal? 0 : 1 + random.nextInt(0x7FFE);     // 1 .. 0x7FFE
        BigInteger significand = new BigInteger(112, random);
        if (subnormal)
          significand = significand.shiftRight(random.nextInt(112));
        final long hi = sign | exponent << 48 | significand.shiftRight(64).longValue();
        final long lo = significand.longValue();                               // lower 64 bits
        return new Ieee754Bits(hi, lo);
      })
      .filter(b -> (b.hi() & 0x7FFF_FFFF_FFFF_FFFFL | b.lo()) != 0)
      .limit(count);
  }

  /**
   * Returns finite Quadruple values with random sign, mantissa ({@code mantHi} and {@code mantLo})
   * and biased exponent. About 1/8 of the values are subnormal (exponent == 0, zero excluded),
   * the rest have exponents evenly distributed over the whole range,
   * excluding {@code EXPONENT_OF_INFINITY}.
   */
  public Stream<Quadruple> quadruples(int count) {
    return Stream.generate(() -> {
        final boolean negative = random.nextBoolean();
        final int exponent = random.nextInt(8) == 0? 0 : random.nextInt();
        return new Quadruple(negative, exponent, random.nextLong(), random.nextLong());
      })
      .filter(q -> q.exponent() != Quadruple.EXPONENT_OF_INFINITY
                   && (q.exponent() != 0 || q.mantHi() != 0 || q.mantLo() != 0))
      .limit(count);
  }

  /**
   * Returns pairs of finite Quadruple values (see {@link #quadruples(int)}) for comparisons.
   * In most pairs, the second value is close to the first one, so that they can be distinguished only
   * by low-order bits: in about 1/6 of the pairs it is an independent random value, in 1/6 an equal value
   * (a different instance), in 1/6 the value with the opposite sign, in 1/6 the value with a flipped bit of
   * {@code mantLo}, in 1/6 with a flipped bit of {@code mantHi}, and in 1/6 with the exponent differing by 1.
   * Flipping bits of subnormal values may yield zeros.
   */
  public Stream<Quadruple[]> quadruplePairs(int count) {
    return quadruples(count).map(a -> new Quadruple[] {a, closeTo(a)});
  }

  private Quadruple closeTo(Quadruple a) {
    final boolean negative = a.isNegative();
    final int exponent = a.exponent();
    final long mantHi = a.mantHi(), mantLo = a.mantLo();
    switch (random.nextInt(6)) {
      case 0:  return quadruples(1).findFirst().get();
      case 1:  return new Quadruple(a);
      case 2:  return new Quadruple(!negative, exponent, mantHi, mantLo);
      case 3:  return new Quadruple(negative, exponent, mantHi, mantLo ^ 1L << random.nextInt(64));
      case 4:  return new Quadruple(negative, exponent, mantHi ^ 1L << random.nextInt(64), mantLo);
      default:
        final int delta = random.nextBoolean()? 1 : -1;
        final int e = exponent + delta == Quadruple.EXPONENT_OF_INFINITY? exponent - delta : exponent + delta;
        return new Quadruple(negative, e, mantHi, mantLo);
    }
  }

  /**
   * Returns normal Quadruple values with random sign and mantissa, and unbiased exponents
   * evenly distributed over the given range (e.g. around the range of {@code double}).
   */
  public Stream<Quadruple> quadruples(int count, int minExponent, int maxExponent) {
    return Stream.generate(() -> new Quadruple(random.nextBoolean(),
                                               Quadruple.EXPONENT_BIAS + minExponent + random.nextInt(maxExponent - minExponent + 1),
                                               random.nextLong(), random.nextLong()))
                 .limit(count);
  }

}
